<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import SampleExperimentHistory from '../components/SampleExperimentHistory.vue'
import SampleResearchReview from '../components/SampleResearchReview.vue'
import SamplePicker from '../components/SamplePicker.vue'
import PageHeading from '../components/PageHeading.vue'
import FormSection from '../components/FormSection.vue'
import StatePanel from '../components/StatePanel.vue'
import ExperimentFields from '../components/ExperimentFields.vue'
import { api, ApiError, errorText } from '../api'
import { useAuth } from '../auth'
import { type Row, type Field, events, sampleStatuses, label, display, dateText, blank, payload, useDraftGuard } from '../experiments/model'
const route=useRoute(),auth=useAuth()
const filter=reactive<Row>({sample_id:'',event_type:'',date_from:'',date_to:''}),page=ref(1),size=ref(20),total=ref(0),rows=ref<Row[]>([]),loading=ref(false),error=ref('')
const sample=ref<Row|null>(null),sampleLoading=ref(false),sampleError=ref(''),process=ref<Row|null>(null),processLoading=ref(false),processError=ref('')
const open=ref(false),saving=ref(false),formError=ref(''),conflict=ref(false),form=ref<Row>({}),baseline=ref('')
const fields:Field[]=[{key:'event_type',label:'事件',type:'select',options:events,required:true},{key:'to_status',label:'追加后的当前状态',type:'select',options:sampleStatuses,required:true},{key:'process_id',label:'执行 ID（装载 / 卸载必填）',type:'id'},{key:'step_id',label:'实际步骤 ID（可空，需属于此次执行）',type:'id'},{key:'measurement_id',label:'测量 ID（可空，需属于当前样品）',type:'id'},{key:'event_at',label:'事件发生时间（本地时间，可空）',type:'datetime'},{key:'location',label:'位置',max:128},{key:'note',label:'备注',type:'textarea'}]
const dirty=()=>open.value&&JSON.stringify(form.value)!==baseline.value
const guard=useDraftGuard(dirty,()=>saving.value)
const canWrite=computed(()=>auth.canWrite&&!!sample.value&&(auth.isAdmin||sample.value.owner_user_id===auth.user?.user_id))
let seq=0,sampleSeq=0,processSeq=0
async function load(){const request=++seq;loading.value=true;error.value='';try{const query={...filter,page:page.value,size:size.value,date_from:filter.date_from?new Date(filter.date_from).toISOString():null,date_to:filter.date_to?new Date(filter.date_to).toISOString():null};const r=await api<Row[]>('/transitions',{query});if(request===seq){rows.value=r.data;total.value=r.meta?.total??0}}catch(e){if(request===seq)error.value=errorText(e)}finally{if(request===seq)loading.value=false}}
async function loadSample(){const request=++sampleSeq;sample.value=null;sampleError.value='';if(!filter.sample_id)return;sampleLoading.value=true;try{const r=await api<Row>(`/samples/${filter.sample_id}`);if(request===sampleSeq)sample.value=r.data}catch(e){if(request===sampleSeq)sampleError.value=errorText(e)}finally{if(request===sampleSeq)sampleLoading.value=false}}
async function search(){if(!await guard.discard())return;open.value=false;page.value=1;await Promise.all([load(),loadSample()])}
async function loadProcess(){const request=++processSeq;process.value=null;processError.value='';if(!form.value.process_id)return;processLoading.value=true;try{const r=await api<Row>(`/processes/${form.value.process_id}`);if(request===processSeq)process.value=r.data}catch(e){if(request===processSeq)processError.value=errorText(e)}finally{if(request===processSeq)processLoading.value=false}}
async function create(){if(!canWrite.value||saving.value)return;form.value=blank(fields,{event_type:'process',to_status:sample.value!.status,process_id:route.query.process_id??''});baseline.value=JSON.stringify(form.value);formError.value='';conflict.value=false;open.value=true;await loadProcess()}
async function close(done?:()=>void){if(await guard.discard()){open.value=false;done?.()}}
function suggestStatus(){const event=form.value.event_type;form.value.to_status=event==='load'?'in_process':event==='unload'||event==='receive'?'available':event==='quarantine'?'quarantined':event==='dispose'?'consumed':sample.value?.status}
async function reloadVersion(){if(saving.value)return;await loadSample();if(sample.value){conflict.value=false;formError.value='已重新获取样品当前状态及版本，输入已保留。请核对后重试。'}}
async function save(){if(saving.value||conflict.value||!canWrite.value)return;formError.value='';try{const body=payload(fields,form.value);if(['load','unload'].includes(body.event_type)&&!body.process_id)throw new Error('装载和卸载必须关联执行');if(body.step_id&&!body.process_id)throw new Error('选择步骤时必须关联执行');if(body.event_type==='load'&&body.to_status!=='in_process')throw new Error('装载后的状态必须为加工中');if(body.event_type==='unload'&&!['available','quarantined','consumed'].includes(body.to_status))throw new Error('卸载后请选择可用、已隔离或已消耗');body.expected_row_version=sample.value!.row_version;saving.value=true;await api(`/samples/${sample.value!.sample_id}/transitions`,{method:'POST',body});open.value=false;await Promise.all([load(),loadSample()]);ElMessage.success('流转已追加；当前状态已由服务更新')}catch(e){formError.value=errorText(e);if(e instanceof ApiError&&e.status===409)conflict.value=true}finally{saving.value=false}}
async function routeEntry(){filter.sample_id=route.query.sample_id??'';page.value=1;open.value=false;await Promise.all([load(),loadSample()])}
watch(()=>route.fullPath,routeEntry)
onMounted(routeEntry)
</script>
<template><div class="experiment-workspace sample-history-view"><PageHeading title="样品科研履历" description="回顾样品来源、每次实验和测量结果。仅展示已记录事实；原始流转事件保留在下方次级视图。"><template #actions><el-button :loading="loading" @click="search">刷新履历</el-button><el-button v-if="canWrite" type="primary" :disabled="sampleLoading" @click="create">追加流转</el-button></template></PageHeading>
<section class="panel"><form class="toolbar" @submit.prevent="search"><SamplePicker v-model="filter.sample_id" :multiple="false" placeholder="搜索样品编号 / 批次"/><el-select v-model="filter.event_type" class="filter-select" clearable placeholder="事件类型" aria-label="事件类型"><el-option v-for="e in events" :key="e" :value="e" :label="label(e)" /></el-select><el-date-picker v-model="filter.date_from" type="datetime" placeholder="事件时间下限" aria-label="事件时间下限" /><el-date-picker v-model="filter.date_to" type="datetime" placeholder="事件时间上限" aria-label="事件时间上限" /><el-button native-type="submit" :loading="loading">筛选 / 选择样品</el-button></form><p class="field-hint history-note">日期筛选不包含事件时间未知的记录。清空日期可查看这些记录；日期不会改变追加顺序。</p>
<StatePanel v-if="sampleError" title="样品详情加载失败" :description="sampleError" tone="error"><el-button @click="loadSample">重试样品</el-button></StatePanel><el-skeleton v-if="sampleLoading" :rows="2" /><div v-else-if="sample" class="history-sample"><strong>{{ sample.sample_code }}</strong><el-tag>当前状态：{{ label(sample.status) }}</el-tag><router-link :to="{path:'/samples',query:{sample_id:sample.sample_id}}" class="el-button is-link">样品档案</router-link><router-link :to="{path:'/processes',query:{create:'1',batch_id:sample.batch_id,sample_id:sample.sample_id}}" class="el-button is-link" v-if="auth.canWrite">创建执行</router-link></div><p v-else-if="!filter.sample_id" class="readonly-note">搜索并选择样品，可查看完整科研履历及原始事件。</p>
<template v-if="sample"><p class="sample-identity">批次 {{sample.batch_code}} · {{sample.batch?.material||'材料未记录'}} · {{label(sample.status)}}</p><details class="sample-properties"><summary>样品档案属性</summary><dl class="detail-grid"><div><dt>所属批次 / 来源</dt><dd><router-link :to="{path:'/batches',query:{batch_id:sample.batch_id}}">{{sample.batch_code}}</router-link> · {{sample.batch?.material||'材料未记录'}}</dd></div><div><dt>母片 / 切割位置</dt><dd>{{sample.parent_sample_id??'母片未记录'}} · {{sample.cut_position||'未记录'}}</dd></div><div><dt>前处理 / 表面</dt><dd>{{sample.pre_treatment||'未记录'}} · {{sample.surface_state||'未记录'}}</dd></div></dl></details><SampleExperimentHistory :sample="sample"/><SampleResearchReview :sample="sample" :review="sample.research_review" :writable="canWrite&&!sample.voided_at"/></template><details><summary>原始事件日志（保留全部追加历史）</summary><StatePanel v-if="error" title="历史加载失败" :description="error" tone="error"><el-button @click="load">重试历史</el-button></StatePanel><div v-else class="table-wrap" v-loading="loading"><el-table :data="rows" empty-text="没有符合条件的历史记录"><el-table-column prop="transition_id" label="追加序号" width="100" /><el-table-column label="样品" min-width="100"><template #default="{row}"><router-link :to="{path:'/sample-history',query:{sample_id:row.sample_id}}">#{{ row.sample_id }}</router-link></template></el-table-column><el-table-column label="事件 / 状态" min-width="180"><template #default="{row}"><strong>{{ label(row.event_type) }}</strong><div>{{ row.from_status?label(row.from_status):'初始' }} → {{ label(row.to_status) }}</div></template></el-table-column><el-table-column label="执行 / 实际步骤" min-width="170"><template #default="{row}"><span v-if="row.context_redacted">关联信息受权限保护</span><template v-else><router-link v-if="row.process_id" :to="{path:'/processes',query:{process_id:row.process_id}}">执行 #{{ row.process_id }}</router-link><span v-else>无关联执行</span><div>步骤 {{ display(row.step_id) }}</div><div v-if="row.measurement_id">测量 #{{ row.measurement_id }}</div></template></template></el-table-column><el-table-column label="事件发生时间" min-width="190"><template #default="{row}">{{ dateText(row.event_at) }}</template></el-table-column><el-table-column label="位置 / 备注" min-width="220"><template #default="{row}"><span v-if="row.context_redacted">关联信息受权限保护</span><template v-else>{{ display(row.location) }}<div class="history-note-text">{{ row.note||'未填写备注' }}</div></template></template></el-table-column><el-table-column label="操作人 ID" width="110"><template #default="{row}">{{ row.context_redacted?'受权限保护':display(row.operator_user_id) }}</template></el-table-column></el-table></div><div class="pagination"><span>共 {{ total }} 条 · 按追加顺序正序</span><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50,100]" layout="prev, pager, next, sizes" @current-change="load" @size-change="page=1;load()" /></div></details></section>
<el-drawer v-model="open" title="追加样品流转" size="min(720px,100vw)" :before-close="close" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving" destroy-on-close><p class="readonly-note">{{ sample?.sample_code }} · 当前 {{ label(sample?.status) }} · 版本 {{ sample?.row_version }}。绑定不等于装载；装载必须从可用进入加工中，卸载必须对应当前占用的执行。</p><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-alert v-if="conflict" title="版本或占用冲突，输入已保留。重载样品后核对状态及执行。" type="warning" :closable="false"><el-button @click="reloadVersion">刷新样品版本并保留输入</el-button></el-alert><el-form label-position="top"><FormSection title="事件与状态" description="事件日期可空。步骤需属于关联执行，样品需已绑定该执行。"><ExperimentFields :fields="fields" :model="form" :disabled="saving" /><el-button :disabled="saving" @click="suggestStatus">按事件建议目标状态</el-button></FormSection><FormSection title="核对执行及步骤" description="读取真实执行详情选择步骤；不会自动绑定或装载样品。"><el-button :loading="processLoading" :disabled="saving" @click="loadProcess">读取执行详情</el-button><StatePanel v-if="processError" title="执行加载失败" :description="processError" tone="error"><el-button @click="loadProcess">重试</el-button></StatePanel><template v-if="process"><p>{{ process.process_code }} · {{ process.samples?.some((s:Row)=>s.sample_id===sample?.sample_id)?'此样品已绑定':'此样品尚未绑定，需先到执行详情绑定' }}</p><el-select v-model="form.step_id" clearable :disabled="saving" placeholder="可选实际步骤" style="width:100%"><el-option v-for="s in process.steps" :key="s.step_id" :value="s.step_id" :label="`${s.step_index} · ${label(s.step_kind)} · #${s.step_id}`" /></el-select></template></FormSection></el-form><template #footer><div class="form-footer"><el-button :disabled="saving" @click="close()">取消</el-button><el-button type="primary" :loading="saving" :disabled="saving||conflict||!sample" @click="save">追加流转</el-button></div></template></el-drawer></div></template>

<style scoped>.sample-history-view :deep(.panel>.form-section-block),.sample-history-view :deep(.panel>[data-testid="sample-research-review"]),.sample-history-view :deep(.panel>details),.sample-identity{margin-left:22px;margin-right:22px}.sample-identity{font-size:13px;color:var(--muted);padding-top:6px}.sample-properties{border-bottom:1px solid var(--line);margin-bottom:20px}.sample-properties summary{color:#086d79;font-size:13px}.sample-properties .detail-grid{margin:12px 0 20px}@media(max-width:640px){.sample-history-view :deep(.panel>.form-section-block),.sample-history-view :deep(.panel>[data-testid="sample-research-review"]),.sample-history-view :deep(.panel>details),.sample-identity{margin-left:16px;margin-right:16px}}</style>
